package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.DosFileAttributes;
import java.nio.file.attribute.PosixFileAttributes;
import java.util.Map;

import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.junit.jupiter.api.Test;

final class GzipFileSystemProviderMutaGate1Test {
  @Test
  void readAttributes_unsupportedAttributeType_throwsUnsupportedOperationWithTypeName() throws IOException {
    Path gzPath = Files.createTempFile("tarballfs-test-", ".gz");
    try {
      try (OutputStream out = Files.newOutputStream(gzPath);
          GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out)) {
        gzOut.write("hello".getBytes(StandardCharsets.UTF_8));
      }

      GzipFileSystemProvider provider = new GzipFileSystemProvider();
      URI uri = URI.create("gzip:" + gzPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path root = fs.getPath("/");
        Path child = fs.getPath("/", gzPath.getFileName().toString());

        UnsupportedOperationException posixEx =
            assertThrows(
                UnsupportedOperationException.class,
                () -> provider.readAttributes(child, PosixFileAttributes.class));
        assertEquals(
            "Unsupported attributes type: " + PosixFileAttributes.class.getName(), posixEx.getMessage());

        UnsupportedOperationException dosEx =
            assertThrows(
                UnsupportedOperationException.class,
                () -> provider.readAttributes(root, DosFileAttributes.class));
        assertEquals(
            "Unsupported attributes type: " + DosFileAttributes.class.getName(), dosEx.getMessage());
      }
    } finally {
      Files.deleteIfExists(gzPath);
    }
  }
}

