import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Map;
import java.util.Set;

import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.junit.jupiter.api.Test;

final class GzipFileSystemProviderMutaGate6Test {
  @Test
  void newFileChannel_returnsReadOnlyChannel_withSizeAndSeekableReads() throws IOException {
    Path gzPath = Files.createTempFile("tarballfs-test-", ".gz");
    try {
      try (OutputStream out = Files.newOutputStream(gzPath);
          GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out)) {
        gzOut.write("hello".getBytes(StandardCharsets.UTF_8));
      }

      GzipFileSystemProvider provider = new GzipFileSystemProvider();
      URI uri = URI.create("gzip:" + gzPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path p = fs.getPath("/", gzPath.getFileName().toString());
        try (FileChannel ch = provider.newFileChannel(p, Set.of(StandardOpenOption.READ))) {
          assertTrue(ch instanceof ReadOnlySeekableFileChannel);
          assertEquals(5L, ch.size());
          assertEquals(0L, ch.position());

          ch.position(1);
          assertEquals(1L, ch.position());

          ByteBuffer buf = ByteBuffer.allocate(16);
          int n = ch.read(buf);
          assertEquals(4, n);
          buf.flip();
          assertEquals("ello", StandardCharsets.UTF_8.decode(buf).toString());
          assertEquals(5L, ch.position());

          buf.clear();
          assertEquals(-1, ch.read(buf));
        }
      }
    } finally {
      Files.deleteIfExists(gzPath);
    }
  }
}

