final class GzipFileSystemProviderMutaGate7Test {
  @Test
  void newByteChannel_readsPayload_reportsSizeAndPosition_andSeeks() throws IOException {
    Path gzPath = Files.createTempFile("tarballfs-test-", ".gz");
    try {
      try (OutputStream out = Files.newOutputStream(gzPath);
          GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out)) {
