          assertNotNull(ch);
          assertTrue(ch.isOpen());
          assertEquals(5L, ch.size());
          assertEquals(0L, ch.position());

          ByteBuffer buf = ByteBuffer.allocate(16);
          int n = ch.read(buf);
          assertEquals(5, n);
          assertEquals(5L, ch.position());
          buf.flip();
          assertEquals("hello", StandardCharsets.UTF_8.decode(buf).toString());

