import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.apache.commons.compress.compressors.gzip.GzipCompressorOutputStream;
import org.apache.commons.compress.compressors.gzip.GzipParameters;
import org.junit.jupiter.api.Test;

final class GzipFileSystemProviderMutaGate8Test {
  @Test
  void newDirectoryStream_appliesFilterToRootEntries() throws IOException {
    Path gzPath = Files.createTempFile("tarballfs-test-", ".gz");
    try {
      GzipParameters params = new GzipParameters();
      params.setFilename("filtered.txt");
      try (OutputStream out = Files.newOutputStream(gzPath);
          GzipCompressorOutputStream gzOut = new GzipCompressorOutputStream(out, params)) {
        gzOut.write("data".getBytes(StandardCharsets.UTF_8));
      }

      GzipFileSystemProvider provider = new GzipFileSystemProvider();
      URI uri = URI.create("gzip:" + gzPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path root = fs.getPath("/");

        DirectoryStream.Filter<Path> rejectAll = p -> false;
        List<String> rejected = new ArrayList<>();
        try (DirectoryStream<Path> ds = provider.newDirectoryStream(root, rejectAll)) {
          for (Path p : ds) {
            rejected.add(p.getFileName().toString());
          }
        }
        assertTrue(rejected.isEmpty());

        DirectoryStream.Filter<Path> acceptMatching = p -> p.getFileName().toString().equals("filtered.txt");
        List<String> accepted = new ArrayList<>();
        try (DirectoryStream<Path> ds = provider.newDirectoryStream(root, acceptMatching)) {
          for (Path p : ds) {
            accepted.add(p.getFileName().toString());
          }
        }
        assertEquals(List.of("filtered.txt"), accepted);
      }
    } finally {
      Files.deleteIfExists(gzPath);
    }
  }
}

