final class GzipFileSystemProviderMutaGate13Test {
  @Test
  void copy_alwaysThrowsUnsupportedOperationException_andCreatesNoTarget() throws IOException {
    Path dir = Files.createTempDirectory("tarballfs-copy-test-");
    try {
      Path source = dir.resolve("source.txt");
      Path target = dir.resolve("target.txt");
      Files.writeString(source, "data");

      GzipFileSystemProvider provider = new GzipFileSystemProvider();

      assertThrows(UnsupportedOperationException.class, () -> provider.copy(source, target));
      assertThrows(
          UnsupportedOperationException.class,
          () -> provider.copy(source, target, StandardCopyOption.REPLACE_EXISTING));
      assertThrows(
          UnsupportedOperationException.class,
          () ->
              provider.copy(
                  source,
                  target,
                  StandardCopyOption.COPY_ATTRIBUTES,
                  StandardCopyOption.REPLACE_EXISTING));

      assertFalse(Files.exists(target));
    } finally {
      Files.deleteIfExists(dir.resolve("source.txt"));
      Files.deleteIfExists(dir.resolve("target.txt"));
      Files.deleteIfExists(dir);
    }
  }
}

