        // Nothing was removed: the payload and the host archive are still intact.
        assertTrue(Files.exists(child));
        assertEquals("hello", Files.readString(child));
        assertTrue(Files.exists(gzPath));
      }
    } finally {
      Files.deleteIfExists(gzPath);
    }
  }
}
